package zone.moddev.mc.ironagearchitecture.roof;

import java.util.*;
import net.minecraft.block.Block;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.*;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.util.text.TextComponentString;
import net.minecraft.world.World;
import zone.moddev.mc.ironagearchitecture.*;

/** Interactions address a paid part, rather than deleting unrelated parts in its voxel. */
public final class RoofDesignInteraction {
    private RoofDesignInteraction(){}
    public static boolean host(IBlockState s){return s.getBlock() instanceof RoofFrameBlock||s.getBlock() instanceof RoofWindowBlock;}
    public static IBlockState state(RoofCell c,BlockPos at){for(RoofWindow n:c.windows)if(n.owner.equals(at))return ArchitectureBlocks.ROOF_WINDOW.getDefaultState().withProperty(RoofWindowBlock.FACING,n.facing).withProperty(RoofWindowBlock.OPEN,n.open).withProperty(RoofWindowBlock.POWERED,n.powered);boolean solid=false;int wood=0;for(RoofPart p:c.parts)if(p.kind!=RoofPart.WINDOW){solid|=p.data.length>0;if(p.kind==RoofPart.TIMBER||p.kind==RoofPart.FASCIA)wood=p.material;}return !solid&&!c.windows.isEmpty()?ArchitectureBlocks.ROOF_WINDOW_PART.getDefaultState():RoofFrameBlock.state(wood,0);}
    public static RoofPart target(World w,BlockPos at,EntityPlayer player){RoofCell c=RoofData.get(w).at(w,at);if(c==null||!c.designed)return null;Vec3d a=zone.moddev.mc.ironagearchitecture.block.SmartThatchBlock.eyes(player),b=a.add(zone.moddev.mc.ironagearchitecture.block.SmartThatchBlock.look(player).scale(player.capabilities.isCreativeMode?6:5));RayTraceResult hit=RoofMeshes.get(c,0).trace(at,a,b);return hit!=null&&hit.hitInfo instanceof Integer&&((Integer)hit.hitInfo)<c.parts.size()?c.parts.get((Integer)hit.hitInfo):null;}
    private static RoofPlan plan(World w,RoofCell c){RoofPlan p=RoofData.get(w).interaction(c.plan,c.owner);return p;}
    public static boolean use(World w,BlockPos at,EntityPlayer player,ItemStack held,EnumHand hand){RoofCell c=RoofData.get(w).at(w,at);if(c==null||!c.designed)return false;if(held!=null&&held.getItem() instanceof RoofClipboardItem)return false;if(w.isRemote)return true;RoofPart target=target(w,at,player);if(target==null)return true;if(target.kind==RoofPart.WINDOW)return RoofWindowController.toggle(w,at,target.id,player);
        if(player.isSneaking()&&held==null){if(target.kind==RoofPart.COVER&&target.material!=0){ItemStack old=RoofMaterials.item(target);if(change(w,c,target,target.withMaterial(0),player)&&!player.capabilities.isCreativeMode)give(player,old);return true;}if(target.kind==RoofPart.GUTTER||target.kind==RoofPart.SOFFIT)return remove(w,at,target.id,player,!player.capabilities.isCreativeMode);}
        int cover=0;if(held!=null)for(int i=1;i<4;i++){ItemStack item=RoofConstruction.coverItem(i);if(item!=null&&held.isItemEqual(item))cover=i;}
        if(cover>0){if(target.kind!=RoofPart.COVER){target=null;for(RoofPart p:c.parts)if(p.kind==RoofPart.COVER){target=p;break;}}if(target==null){player.sendStatusMessage(new TextComponentString("Fit covering to a sloping roof section."));return true;}if(target.material!=0)return true;if(change(w,c,target,target.withMaterial(cover),player)&&!player.capabilities.isCreativeMode){held.stackSize--;if(held.stackSize==0)player.setHeldItem(hand,null);}return true;}return false;
    }
    static void give(EntityPlayer p,ItemStack s){if(s!=null&&!p.inventory.addItemStackToInventory(s))p.dropItem(s,false);}
    public static boolean change(World w,RoofCell cell,RoofPart old,RoofPart next,EntityPlayer player){RoofPlan p=plan(w,cell);if(p==null||RoofConstruction.busy(w,p.id))return false;Map<Long,RoofCell> all=RoofData.get(w).owned(w,p),changes=new TreeMap<>();for(Map.Entry<Long,RoofCell> e:all.entrySet()){RoofCell c=e.getValue();boolean found=false;List<RoofPart> parts=new ArrayList<>();for(RoofPart a:c.parts){if(a.id.equals(old.id)){found=true;if(next!=null)parts.add(new RoofPart(a.id,a.root,a.kind,next.material,a.data,a.facing));}else parts.add(a);}if(found){if(next!=null&&old.kind==RoofPart.COVER&&old.material==0&&next.material>0){RoofCell added=new RoofCell(c.plan,c.owner,Collections.singletonList(new RoofPart(old.id,old.root,old.kind,next.material,old.data,old.facing)),Collections.emptyList());for(RoofWindow window:c.windows)if(window.open)for(AxisAlignedBB leaf:RoofWindowGeometry.movingBoxes(window))for(AxisAlignedBB cover:RoofMeshes.get(added,0).boxes)if(leaf.intersectsWith(cover)){if(player!=null)player.sendStatusMessage(new TextComponentString("Close the window before fitting this covering."));return false;}for(AxisAlignedBB box:RoofMeshes.get(added,0).boxes)if(!w.checkNoEntityCollision(box.offset(BlockPos.fromLong(e.getKey())))){if(player!=null)player.sendStatusMessage(new TextComponentString("Move clear before fitting the covering."));return false;}}BlockPos at=BlockPos.fromLong(e.getKey());if(player!=null&&(!w.isBlockModifiable(player,at)||!player.canPlayerEdit(at,EnumFacing.UP,RoofMaterials.item(old))))return false;changes.put(e.getKey(),new RoofCell(c.plan,c.owner,parts,c.windows));}}
        RoofConstruction.changing=true;try{for(Map.Entry<Long,RoofCell> e:changes.entrySet())write(w,BlockPos.fromLong(e.getKey()),e.getValue());}finally{RoofConstruction.changing=false;}return !changes.isEmpty();}
    public static void write(World w,BlockPos at,RoofCell c){if(!host(w.getBlockState(at))&&!w.isAirBlock(at)){RoofData.get(w).put(w,at,null);return;}if(c.empty()){RoofData.get(w).put(w,at,null);if(host(w.getBlockState(at)))w.setBlockToAir(at);}else{RoofData.get(w).put(w,at,c);IBlockState s=state(c,at);if(w.getBlockState(at).getBlock()!=s.getBlock()||!w.getBlockState(at).equals(s))w.setBlockState(at,s,3);else w.markBlockRangeForRenderUpdate(at,at);}w.checkLight(at);}
    public static boolean mine(World w,BlockPos at,EntityPlayer player){RoofCell c=RoofData.get(w).at(w,at);if(c==null||!c.designed)return false;if(RoofConstruction.busy(w,c.plan)){player.sendStatusMessage(new TextComponentString("Cancel construction at the workbench before dismantling it."));return false;}RoofPart p=target(w,at,player);return p!=null&&remove(w,at,p.id,player,!player.capabilities.isCreativeMode);}
    public static boolean remove(World w,BlockPos at,String id,EntityPlayer player,boolean drops){RoofCell c=RoofData.get(w).at(w,at);if(c==null||!c.designed)return false;for(RoofPart part:c.parts)if(part.id.equals(id)&&!w.isBlockLoaded(part.root))return false;for(RoofPart part:c.parts)if(part.id.equals(id)){RoofCell root=RoofData.get(w).at(w,part.root);if(root==null||root.parts.stream().noneMatch(a->a.id.equals(id)))return false;}for(RoofWindow n:c.windows)if(n.id.equals(id))for(BlockPos occupied:RoofWindowGeometry.candidates(n))if(!w.isBlockLoaded(occupied)){if(player!=null)player.sendStatusMessage(new TextComponentString("Bring the whole window into loaded chunks before removing it."));return false;}RoofPlan plan=plan(w,c);if(plan==null||RoofConstruction.busy(w,c.plan))return false;Map<Long,RoofCell> all=RoofData.get(w).owned(w,plan),changes=new TreeMap<>();Map<String,ItemStack> recoveredItems=new LinkedHashMap<>();Set<String> removed=new HashSet<>();removed.add(id);removed.add("gutter:"+id);removed.add("lining:"+id);ItemStack recovered=null;for(Map.Entry<Long,RoofCell> e:all.entrySet()){RoofCell a=e.getValue();List<RoofPart> ps=new ArrayList<>();boolean changed=false;for(RoofPart p:a.parts)if(removed.contains(p.id)){changed=true;recovered=RoofMaterials.item(p);recoveredItems.put(p.id,recovered);}else ps.add(p);List<RoofWindow> ws=new ArrayList<>();for(RoofWindow n:a.windows)if(n.id.equals(id))changed=true;else ws.add(n);if(changed){BlockPos pos=BlockPos.fromLong(e.getKey());if(player!=null&&(!w.isBlockModifiable(player,pos)||!player.canPlayerEdit(pos,EnumFacing.UP,recovered)))return false;changes.put(e.getKey(),new RoofCell(a.plan,a.owner,ps,ws));}}
        for(RoofWindow n:c.windows)if(n.id.equals(id))RoofData.get(w).removeWindow(c.plan,id);RoofConstruction.changing=true;try{for(Map.Entry<Long,RoofCell> e:changes.entrySet())write(w,BlockPos.fromLong(e.getKey()),e.getValue());}finally{RoofConstruction.changing=false;}if(drops)for(ItemStack item:recoveredItems.values())if(item!=null){if(player==null)Block.spawnAsEntity(w,at,item);else give(player,item);}RoofGutters.refreshCaps(w,plan);return !changes.isEmpty();}
    public static void replaced(World w,BlockPos at,RoofCell old,boolean drops){for(RoofWindow n:old.windows)RoofData.get(w).removeWindow(old.plan,n.id);RoofPlan p=plan(w,old);if(p==null){RoofData.get(w).put(w,at,null);return;}Map<String,ItemStack> ids=new LinkedHashMap<>();for(RoofPart part:old.parts)ids.put(part.id,RoofMaterials.item(part));Map<Long,RoofCell> all=RoofData.get(w).owned(w,p);for(RoofCell cell:all.values())for(RoofPart part:cell.parts)if(ids.containsKey(part.id.substring(Math.min(7,part.id.length())))&&(part.id.startsWith("gutter:")||part.id.startsWith("lining:")))ids.put(part.id,RoofMaterials.item(part));RoofConstruction.changing=true;try{for(Map.Entry<Long,RoofCell> e:all.entrySet()){if(e.getKey()==at.toLong())continue;RoofCell c=e.getValue();List<RoofPart> ps=new ArrayList<>();List<RoofWindow> ws=new ArrayList<>();for(RoofPart part:c.parts)if(!ids.containsKey(part.id))ps.add(part);for(RoofWindow n:c.windows)if(!ids.containsKey(n.id))ws.add(n);if(ps.size()!=c.parts.size()||ws.size()!=c.windows.size())write(w,BlockPos.fromLong(e.getKey()),new RoofCell(c.plan,c.owner,ps,ws));}RoofData.get(w).put(w,at,null);if(host(w.getBlockState(at)))w.setBlockToAir(at);}finally{RoofConstruction.changing=false;}if(drops)for(ItemStack item:ids.values())if(item!=null)Block.spawnAsEntity(w,at,item);}
}
